properties.serializedData:
{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "<div style='padding:16px 20px;background:#eff6fc;border-left:3px solid #0078d4;border-radius:6px;margin-bottom:8px'><h2 style='margin:0 0 4px 0;color:#0078d4;font-size:18px'>Microsoft Foundry Readiness Assessment</h2><p style='margin:0;font-size:13px;color:#605e5c'>Evaluates your Azure environment for Microsoft Foundry-based AI workloads across nine readiness pillars aligned with the Azure AI Landing Zone. Select subscription(s) to run the assessment.</p></div>"
      },
      "name": "header"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "parameters": [
          {
            "id": "subscription",
            "version": "KqlParameterItem/1.0",
            "name": "Subscription",
            "type": 6,
            "isRequired": true,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "includeAll": true,
              "showDefault": false
            },
            "defaultValue": "value::all"
          },
          {
            "id": "pillar-bars-param",
            "version": "KqlParameterItem/1.0",
            "name": "PillarBarsHtml",
            "type": 1,
            "query": "resources\n| summarize\n    purview=countif(type=='microsoft.purview/accounts'),\n    databricks=countif(type=='microsoft.databricks/workspaces'),\n    adf=countif(type=='microsoft.datafactory/factories'),\n    adf_git=countif(type=='microsoft.datafactory/factories' and isnotnull(properties.repoConfiguration.repositoryName)),\n    adls=countif(type=='microsoft.storage/storageaccounts' and tobool(properties.isHnsEnabled)==true),\n    aisearch=countif(type=='microsoft.search/searchservices'),\n    redis=countif(type in ('microsoft.cache/redis','microsoft.cache/redisenterprise')),\n    cosmos=countif(type=='microsoft.documentdb/databaseaccounts'),\n    docint=countif(type=='microsoft.cognitiveservices/accounts' and kind in ('FormRecognizer','DocumentIntelligence')),\n    foundry=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices'),\n    foundry_id=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and isnotnull(identity)),\n    foundry_nokey=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and tobool(properties.disableLocalAuth)==true),\n    foundry_cmk=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and isnotnull(properties.encryption.keyVaultProperties)),\n    foundry_regions=dcountif(location, type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices'),\n    fproject=countif(type=~'microsoft.cognitiveservices/accounts/projects'),\n    fproject_id=countif(type=~'microsoft.cognitiveservices/accounts/projects' and isnotnull(identity.principalId)),\n    keyvault=countif(type=='microsoft.keyvault/vaults'),\n    kv_hardened=countif(type=='microsoft.keyvault/vaults' and tobool(properties.enableRbacAuthorization)==true and tobool(properties.enableSoftDelete)==true and tobool(properties.enablePurgeProtection)==true),\n    foundry_pe=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and array_length(properties.privateEndpointConnections) > 0),\n    apim=countif(type=='microsoft.apimanagement/service'),\n    apim_mi=countif(type=='microsoft.apimanagement/service' and isnotnull(identity)),\n    appinsights=countif(type=='microsoft.insights/components'),\n    vnet=countif(type=='microsoft.network/virtualnetworks'),\n    nsg=countif(type=='microsoft.network/networksecuritygroups'),\n    firewall=countif(type=='microsoft.network/azurefirewalls'),\n    appgw_waf=countif(type=='microsoft.network/applicationgateways' and isnotnull(properties.webApplicationFirewallConfiguration)),\n    bastion=countif(type=='microsoft.network/bastionhosts'),\n    pdz_aiservices=countif(type=='microsoft.network/privatednszones' and (name has 'cognitiveservices' or name has 'openai' or name has 'azure-api'))\n| extend Pillars = pack_array(\n        strcat('Foundry Inventory|1|6|', tostring(iff(foundry>0,2,0) + iff(foundry_id>0,1,0) + iff(fproject>0,2,0) + iff(fproject_id>0,1,0))),\n        strcat('Data Management & Governance|2|7|', tostring(iff(purview>0,3,0) + iff(databricks>0,2,0) + iff(adf_git>0,2,iff(adf>0,1,0)))),\n        strcat('Retrieval & Context Enablement|3|5|', tostring(iff(aisearch>0,2,0) + iff(redis>0,1,0) + iff(cosmos>0,1,0) + iff(docint>0,1,0))),\n        strcat('Responsible AI|4|2|', tostring(iff(foundry>0,2,0))),\n        strcat('Identity & Access|5|5|', tostring(iff(foundry_id>0,2,0) + iff(apim_mi>0,1,iff(apim>0,0,0)) + iff(foundry_nokey>0,2,0))),\n        strcat('Network & Security|6|12|', tostring(iff(kv_hardened>0,3,iff(keyvault>0,1,0)) + iff(foundry_pe>0,2,0) + iff(apim>0,2,0) + iff(pdz_aiservices>0,1,0) + iff(firewall>0,1,0) + iff(appgw_waf>0,1,0) + iff(bastion>0,1,0) + iff(foundry_cmk>0,1,0))),\n        strcat('Policy & Compliance|7|3|', tostring(iff(foundry_pe>0,1,0) + iff(kv_hardened>0,1,0) + iff(foundry_cmk>0,1,0))),\n        strcat('Cost & Operations|8|5|', tostring(iff(foundry_regions>=2,2,iff(foundry>0,1,0)) + iff(appinsights>0,2,0) + iff(apim>0,1,0))),\n        strcat('Monitoring & Operations|9|5|', tostring(iff(appinsights>0,3,0) + iff(foundry_id>0,2,0))))\n| mv-expand Pillars to typeof(string)\n| extend parts = split(Pillars, '|')\n| extend Pillar=tostring(parts[0]), SortOrder=toint(parts[1]), MaxScore=toint(parts[2]), WeightedScore=toint(parts[3])\n| extend ScorePercent=toint(round(100.0*WeightedScore/MaxScore, 0))\n| order by SortOrder asc\n| extend BarColor=iff(ScorePercent>=75, '#00b294', iff(ScorePercent>=40, '#ff8c00', '#e81123'))\n| extend row=strcat('<div style=\"display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid #f3f2f1\"><div style=\"min-width:240px;font-size:13px;color:#0078d4;font-weight:600\">', Pillar, '</div><div style=\"flex:1;height:12px;background:#edebe9;border-radius:2px;overflow:hidden;min-width:120px\"><div style=\"height:100%;width:', tostring(ScorePercent), '%;background:', BarColor, ';border-radius:2px\"></div></div><span style=\"min-width:44px;text-align:right;font-size:13px;font-weight:600;color:#323130\">', tostring(ScorePercent), '%</span></div>')\n| summarize allrows=strcat_array(make_list(row), '')\n| project allrows",
            "isHiddenWhenLocked": true,
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "{Subscription}"
            ]
          },
          {
            "id": "score-card-param",
            "version": "KqlParameterItem/1.0",
            "name": "ScoreCardHtml",
            "type": 1,
            "query": "resources\n| summarize\n    purview=countif(type=='microsoft.purview/accounts'),\n    databricks=countif(type=='microsoft.databricks/workspaces'),\n    adf=countif(type=='microsoft.datafactory/factories'),\n    adf_git=countif(type=='microsoft.datafactory/factories' and isnotnull(properties.repoConfiguration.repositoryName)),\n    adls=countif(type=='microsoft.storage/storageaccounts' and tobool(properties.isHnsEnabled)==true),\n    aisearch=countif(type=='microsoft.search/searchservices'),\n    redis=countif(type in ('microsoft.cache/redis','microsoft.cache/redisenterprise')),\n    cosmos=countif(type=='microsoft.documentdb/databaseaccounts'),\n    docint=countif(type=='microsoft.cognitiveservices/accounts' and kind in ('FormRecognizer','DocumentIntelligence')),\n    foundry=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices'),\n    foundry_id=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and isnotnull(identity)),\n    foundry_nokey=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and tobool(properties.disableLocalAuth)==true),\n    foundry_cmk=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and isnotnull(properties.encryption.keyVaultProperties)),\n    foundry_regions=dcountif(location, type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices'),\n    fproject=countif(type=~'microsoft.cognitiveservices/accounts/projects'),\n    fproject_id=countif(type=~'microsoft.cognitiveservices/accounts/projects' and isnotnull(identity.principalId)),\n    keyvault=countif(type=='microsoft.keyvault/vaults'),\n    kv_hardened=countif(type=='microsoft.keyvault/vaults' and tobool(properties.enableRbacAuthorization)==true and tobool(properties.enableSoftDelete)==true and tobool(properties.enablePurgeProtection)==true),\n    foundry_pe=countif(type=='microsoft.cognitiveservices/accounts' and kind=~'AIServices' and array_length(properties.privateEndpointConnections) > 0),\n    apim=countif(type=='microsoft.apimanagement/service'),\n    apim_mi=countif(type=='microsoft.apimanagement/service' and isnotnull(identity)),\n    appinsights=countif(type=='microsoft.insights/components'),\n    vnet=countif(type=='microsoft.network/virtualnetworks'),\n    nsg=countif(type=='microsoft.network/networksecuritygroups'),\n    firewall=countif(type=='microsoft.network/azurefirewalls'),\n    appgw_waf=countif(type=='microsoft.network/applicationgateways' and isnotnull(properties.webApplicationFirewallConfiguration)),\n    bastion=countif(type=='microsoft.network/bastionhosts'),\n    pdz_aiservices=countif(type=='microsoft.network/privatednszones' and (name has 'cognitiveservices' or name has 'openai' or name has 'azure-api'))\n| extend TotalWeighted = (iff(foundry>0,2,0) + iff(foundry_id>0,1,0) + iff(fproject>0,2,0) + iff(fproject_id>0,1,0)) + (iff(purview>0,3,0) + iff(databricks>0,2,0) + iff(adf_git>0,2,iff(adf>0,1,0))) + (iff(aisearch>0,2,0) + iff(redis>0,1,0) + iff(cosmos>0,1,0) + iff(docint>0,1,0)) + (iff(foundry>0,2,0)) + (iff(foundry_id>0,2,0) + iff(apim_mi>0,1,iff(apim>0,0,0)) + iff(foundry_nokey>0,2,0)) + (iff(kv_hardened>0,3,iff(keyvault>0,1,0)) + iff(foundry_pe>0,2,0) + iff(apim>0,2,0) + iff(pdz_aiservices>0,1,0) + iff(firewall>0,1,0) + iff(appgw_waf>0,1,0) + iff(bastion>0,1,0) + iff(foundry_cmk>0,1,0)) + (iff(foundry_pe>0,1,0) + iff(kv_hardened>0,1,0) + iff(foundry_cmk>0,1,0)) + (iff(foundry_regions>=2,2,iff(foundry>0,1,0)) + iff(appinsights>0,2,0) + iff(apim>0,1,0)) + (iff(appinsights>0,3,0) + iff(foundry_id>0,2,0))\n| extend MaxTotal = 50\n| extend S = toint(round(100.0 * TotalWeighted / MaxTotal, 0))\n| extend ScoreColor=iff(S>=80, '#107c10', iff(S>=50, '#d69900', '#d13438'))\n| extend RingPct = S * 2.51327\n| extend html=strcat('<div style=\"display:flex;flex-direction:column;align-items:center;justify-content:center;padding:12px 8px\"><div style=\"font-size:13px;font-weight:600;color:#605e5c;text-transform:uppercase;letter-spacing:1px;margin-bottom:12px\">AI Readiness Score</div><div style=\"position:relative;width:160px;height:160px\"><svg viewBox=\"0 0 100 100\" style=\"transform:rotate(-90deg)\"><circle cx=\"50\" cy=\"50\" r=\"40\" fill=\"none\" stroke=\"#edebe9\" stroke-width=\"8\"/><circle cx=\"50\" cy=\"50\" r=\"40\" fill=\"none\" stroke=\"', ScoreColor, '\" stroke-width=\"8\" stroke-dasharray=\"', tostring(RingPct), ' 251.327\" stroke-linecap=\"round\"/></svg><div style=\"position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);text-align:center\"><div style=\"font-size:38px;font-weight:700;color:', ScoreColor, ';line-height:1\">', tostring(S), '%</div></div></div></div>')\n| project html",
            "isHiddenWhenLocked": true,
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "{Subscription}"
            ]
          }
        ],
        "style": "pills"
      },
      "name": "parameters"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "title": "Assessment Summary",
        "items": [
          {
            "type": 1,
            "content": {
              "json": "<div style=\"border:1px solid #edebe9;border-radius:8px;background:#fff;box-shadow:0 2px 8px rgba(0,0,0,0.08);height:100%\">{ScoreCardHtml}</div>"
            },
            "customWidth": "25",
            "name": "overall-score-tile"
          },
          {
            "type": 1,
            "content": {
              "json": "<div style=\"padding:0 4px\">\r\n\r\n**Readiness by Pillar**\r\n\r\n{PillarBarsHtml}\r\n</div>"
            },
            "customWidth": "75",
            "name": "pillar-grid"
          }
        ]
      },
      "name": "summary-group"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "title": "AI Resource Landscape",
        "expandable": true,
        "expanded": false,
        "items": [
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:8px 0;font-size:12px;color:#605e5c'>Geographic distribution of Foundry-relevant resources across selected subscriptions. Informational; does not affect the score.</div>"
            },
            "name": "landscape-description"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type in~ (\n    'microsoft.cognitiveservices/accounts',\n    'microsoft.cognitiveservices/accounts/projects',\n    'microsoft.search/searchservices',\n    'microsoft.cache/redis',\n    'microsoft.cache/redisenterprise',\n    'microsoft.documentdb/databaseaccounts',\n    'microsoft.purview/accounts',\n    'microsoft.databricks/workspaces',\n    'microsoft.datafactory/factories',\n    'microsoft.apimanagement/service',\n    'microsoft.insights/components'\n  )\n| where type !~ 'microsoft.cognitiveservices/accounts'\n    or kind in~ ('AIServices','FormRecognizer','DocumentIntelligence')\n| summarize resourceCount = count() by location\n| order by resourceCount desc",
              "size": 3,
              "title": "AI Resources by Region",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscription}"
              ],
              "visualization": "map",
              "mapSettings": {
                "locInfo": "AzureLoc",
                "locInfoColumn": "location",
                "sizeSettings": "resourceCount",
                "sizeAggregation": "Sum",
                "legendMetric": "resourceCount",
                "legendAggregation": "Sum",
                "itemColorSettings": {
                  "nodeColorField": "resourceCount",
                  "colorAggregation": "Sum",
                  "type": "heatmap",
                  "heatmapPalette": "greenRed"
                }
              },
              "noDataMessage": "No AI resources found in the selected subscription(s).",
              "noDataMessageStyle": 4
            },
            "name": "landscape-map"
          }
        ]
      },
      "name": "landscape-group"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "title": "Foundry Inventory",
        "expandable": true,
        "expanded": true,
        "items": [
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:8px 0;font-size:12px;color:#605e5c'>Inventory of Microsoft Foundry resources and projects. Foundry is identified as <code>microsoft.cognitiveservices/accounts</code> with <code>kind = AIServices</code>.</div>"
            },
            "name": "fdy-description"
          },
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:16px 0 4px 0;border-bottom:1px solid #edebe9;padding-bottom:4px'><span style='font-size:11px;font-weight:600;color:#0078d4;text-transform:uppercase;letter-spacing:.5px'>FDY-001</span>&nbsp;&nbsp;<span style='font-size:14px;font-weight:600;color:#323130'>Foundry Accounts</span><span style='font-size:12px;color:#605e5c;margin-left:8px'>Microsoft Foundry account inventory with identity, network, encryption, and auth configuration.</span></div>"
            },
            "name": "fdy-001-header"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type == 'microsoft.cognitiveservices/accounts' and kind =~ 'AIServices'\n| extend hasIdentity = isnotnull(identity),\n         disableLocalAuth = tobool(properties.disableLocalAuth),\n         publicAccess = tostring(properties.publicNetworkAccess),\n         cmkEnabled = isnotnull(properties.encryption.keyVaultProperties),\n         networkInjection = tostring(properties.networkInjections),\n         peCount = array_length(properties.privateEndpointConnections)\n| project name, location, hasIdentity, disableLocalAuth, publicAccess, cmkEnabled, peCount, networkInjection, subscriptionId",
              "size": 3,
              "title": "Foundry Accounts",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscription}"
              ],
              "visualization": "table",
              "noDataMessage": "No resources found in the selected subscription(s).",
              "noDataMessageStyle": 4,
              "gridSettings": {
                "formatters": [
                  {
                    "columnMatch": "hasIdentity",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "icons",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "true",
                          "representation": "success",
                          "text": "Yes"
                        },
                        {
                          "operator": "Default",
                          "representation": "warning",
                          "text": "No"
                        }
                      ]
                    }
                  },
                  {
                    "columnMatch": "disableLocalAuth",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "icons",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "true",
                          "representation": "success",
                          "text": "Disabled"
                        },
                        {
                          "operator": "Default",
                          "representation": "warning",
                          "text": "Enabled"
                        }
                      ]
                    }
                  },
                  {
                    "columnMatch": "cmkEnabled",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "icons",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "true",
                          "representation": "success",
                          "text": "Yes (CMK)"
                        },
                        {
                          "operator": "Default",
                          "representation": "warning",
                          "text": "MMK"
                        }
                      ]
                    }
                  }
                ]
              }
            },
            "name": "fdy-001-query"
          },
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:16px 0 4px 0;border-bottom:1px solid #edebe9;padding-bottom:4px'><span style='font-size:11px;font-weight:600;color:#0078d4;text-transform:uppercase;letter-spacing:.5px'>FDY-002</span>&nbsp;&nbsp;<span style='font-size:14px;font-weight:600;color:#323130'>Foundry Projects</span><span style='font-size:12px;color:#605e5c;margin-left:8px'>Projects organize models, data, and agents within a Foundry account.</span></div>"
            },
            "name": "fdy-002-header"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.cognitiveservices/accounts/projects'\n| extend hasIdentity = isnotnull(identity.principalId),\n         endpoint = tostring(properties.endpoints)\n| project name, location, hasIdentity, endpoint, subscriptionId",
              "size": 3,
              "title": "Foundry Projects",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscription}"
              ],
              "visualization": "table",
              "noDataMessage": "No resources found in the selected subscription(s).",
              "noDataMessageStyle": 4,
              "gridSettings": {
                "formatters": [
                  {
                    "columnMatch": "hasIdentity",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "icons",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "true",
                          "representation": "success",
                          "text": "Yes"
                        },
                        {
                          "operator": "Default",
                          "representation": "warning",
                          "text": "No"
                        }
                      ]
                    }
                  }
                ]
              }
            },
            "name": "fdy-002-query"
          }
        ]
      },
      "name": "foundry-inventory-group"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "title": "Data Management & Governance",
        "expandable": true,
        "expanded": false,
        "items": [
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:16px 0 4px 0;border-bottom:1px solid #edebe9;padding-bottom:4px'><span style='font-size:11px;font-weight:600;color:#0078d4;text-transform:uppercase;letter-spacing:.5px'>DMG-001</span>&nbsp;&nbsp;<span style='font-size:14px;font-weight:600;color:#323130'>Purview Accounts</span><span style='font-size:12px;color:#605e5c;margin-left:8px'>Microsoft Purview &#x2014; Unified data governance platform.</span></div>"
            },
            "name": "dmg-001-header"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type == 'microsoft.purview/accounts'\n| project name, location, subscriptionId, properties",
              "size": 3,
              "title": "Purview Accounts",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscription}"
              ],
              "visualization": "table",
              "noDataMessage": "No resources found in the selected subscription(s).",
              "noDataMessageStyle": 4
            },
            "name": "dmg-001-query"
          },
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:16px 0 4px 0;border-bottom:1px solid #edebe9;padding-bottom:4px'><span style='font-size:11px;font-weight:600;color:#0078d4;text-transform:uppercase;letter-spacing:.5px'>DMG-002</span>&nbsp;&nbsp;<span style='font-size:14px;font-weight:600;color:#323130'>Purview Scan Rulesets</span><span style='font-size:12px;color:#605e5c;margin-left:8px'>Validate scan rulesets are configured for data discovery.</span></div>"
            },
            "name": "dmg-002-header"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type == 'microsoft.purview/accounts'\n| where isnotnull(properties.scanRulesets)\n| project name, location, subscriptionId, scanRulesets=properties.scanRulesets",
              "size": 3,
              "title": "Purview Scan Rulesets",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscription}"
              ],
              "visualization": "table",
              "noDataMessage": "No resources found in the selected subscription(s).",
              "noDataMessageStyle": 4
            },
            "name": "dmg-002-query"
          },
          {
            "type": 1,
            "content": {
              "json": "<div style='margin:16px 0 4px 0;border-bottom:1px solid #edebe9;padding-bottom:4px'><span style='font-size:11px;font-weight:600;color:#0078d4;text-transform:uppercase;letter-spacing:.5px'>DMG-003</span>&nbsp;&nbsp;<span style='font-size:14px;font-weight:600;color:#323130'>Data Classification Rules</span><span style='font-size:12px;color:#605e5c;margin-left:8px'>Cloud connector configurations enabling data classification.</span></div>"
            },
            "name": "dmg-003-header"
